// Hand-written `@orpc/contract` stub for the flowatlas fixture suite.
//
// A contract is a tree of declarations with no code: each link hands back
// another builder, and none of them ends in a handler, which is what keeps a
// contract from being read as a tree of ways in.

export interface ContractBuilder {
  route(route: { method?: string; path?: string; tags?: string[] }): ContractBuilder;
  input(schema: unknown): ContractBuilder;
  output(schema: unknown): ContractBuilder;
  errors(map: Record<string, { message?: string; status?: number; data?: unknown }>): ContractBuilder;
  prefix(prefix: string): ContractBuilder;
  router<T>(router: T): T;
}

export declare const oc: ContractBuilder;
